"""Copy the G1 + Wuji Hand 2 model generated by g1-wuji-retargeting; no downloads.

The retargeting repository owns the assembly (official URDFs, pinned revisions and
provisional wrist mounts), so trajectories retargeted there use the same hand
placement as this simulator. Only the robot is kept: the generated floor, lights,
option and visual settings are dropped because each scene supplies its own.
"""
from pathlib import Path
import argparse
import hashlib
import json
import shutil
import subprocess
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[1]
DESTINATION = ROOT/'assets/robot_wuji'


def sha256(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, default=Path.home()/'Projects/g1-wuji-retargeting',
                        help='g1-wuji-retargeting checkout after ./fetch_assets.sh and build.py')
    args = parser.parse_args()
    source = args.source.expanduser().resolve()
    generated = source/'generated'
    scene_path = generated/'scene.xml'
    if not scene_path.is_file():
        raise FileNotFoundError(f'{scene_path} is missing; run ./fetch_assets.sh and build.py in {source} first')
    root = ET.parse(scene_path).getroot()
    if len(root.findall('./actuator/position')) != 69:
        raise ValueError('Expected the 69-actuator G1 + two Wuji Hand 2 model')
    for tag in ('option', 'visual'):
        for node in root.findall(tag):
            root.remove(node)
    world = root.find('worldbody')
    for node in list(world):
        if not (node.tag == 'body' and node.get('name') == 'pelvis'):
            world.remove(node)
    if (DESTINATION/'meshes').is_dir():
        shutil.rmtree(DESTINATION/'meshes')
    (DESTINATION/'meshes').mkdir(parents=True)
    meshes = []
    for mesh in root.findall('./asset/mesh'):
        name = Path(mesh.get('file')).name
        original = generated/'meshes'/name
        shutil.copy2(original, DESTINATION/'meshes'/name)
        mesh.set('file', name)
        meshes.append({'file': name, 'sha256': sha256(original)})
    root.set('model', 'G1 Wuji Hand 2')
    root.find('compiler').set('meshdir', 'meshes')
    ET.indent(root)
    ET.ElementTree(root).write(DESTINATION/'g1_wuji.xml', encoding='unicode')
    try:
        commit = subprocess.check_output(['git', '-C', str(source), 'rev-parse', 'HEAD'], text=True).strip()
    except (OSError, subprocess.CalledProcessError):
        commit = None
    upstream = json.loads((generated/'provenance.json').read_text())
    (DESTINATION/'provenance.json').write_text(json.dumps({
        'source_repository': 'https://github.com/LidarDexManip/g1-wuji-retargeting',
        'source_commit': commit,
        'source_scene_sha256': sha256(scene_path),
        'upstream_provenance': upstream,
        'warning': 'Wuji Hand 2 Beta 2 with provisional G1 wrist mounts from the retargeting repository. '
                   'Gains, friction and mounts are not hardware-calibrated. Upstream asset terms remain applicable.',
        'meshes': meshes,
    }, indent=2)+'\n')
    print(f'Prepared {len(meshes)} meshes and {DESTINATION/"g1_wuji.xml"}')


if __name__ == '__main__':
    main()
